// GetCreatorMarketplaceCreatorsParams defines parameters for GetCreatorMarketplaceCreators.
type GetCreatorMarketplaceCreatorsParams struct {
	AccessToken string  `form:"access_token" json:"access_token"`
	Fields      *string `form:"fields,omitempty" json:"fields,omitempty"`

	// CreatorCountries Filter creators based on their country. Input will be the country ISO code. For example: `creator_countries=['US']`
	CreatorCountries *string `form:"creator_countries,omitempty" json:"creator_countries,omitempty"`

	// CreatorMinFollowers Minimum follower count for creators. **Values:** `0`, `10000`, `25000`, `50000`, `75000`, `100000`, `250000`, `1000000`.
	CreatorMinFollowers *GetCreatorMarketplaceCreatorsParamsCreatorMinFollowers `form:"creator_min_followers,omitempty" json:"creator_min_followers,omitempty"`

	// CreatorMaxFollowers Maximum follower count for creators. **Values:** `10000`, `25000`, `50000`, `75000`, `100000`, `250000`, `1000000`.
	CreatorMaxFollowers *GetCreatorMarketplaceCreatorsParamsCreatorMaxFollowers `form:"creator_max_followers,omitempty" json:"creator_max_followers,omitempty"`

	// CreatorAgeBucket Filter creators based on their age range. **Values:** `18_to_24`,  `25_to_34`, `35_to_44`, `45_to_54`, `55_to_64`, `65_and_above`.
	CreatorAgeBucket *GetCreatorMarketplaceCreatorsParamsCreatorAgeBucket `form:"creator_age_bucket,omitempty" json:"creator_age_bucket,omitempty"`

	// CreatorInterests Filter creators based on category list input. **Values:** `ANIMALS_AND_PETS`, `BOOKS_AND_LITERATURE`, `BUSINESS_FINANCE_AND_ECONOMICS`, `EDUCATION_AND_LEARNING`, `BEAUTY`, `FASHION`, `FITNESS_AND_WORKOUTS`, `FOOD_AND_DRINK`, `GAMES_PUZZLES_AND_PLAY`, `HISTORY_AND_PHILOSOPHY`, `HOLIDAYS_AND_CELEBRATIONS`, `HOME_AND_GARDEN`, `MUSIC_AND_AUDIO`, `PERFORMING_ARTS`, `SCIENCE_AND_TECH`, `SPORTS`, `TV_AND_MOVIES`, `TRAVEL_AND_LEISURE_ACTIVITIES`, `VEHICLES_AND_TRANSPORTATION`, `VISUAL_ARTS_ARCHITECTURE_AND_CRAFTS`
	CreatorInterests *string `form:"creator_interests,omitempty" json:"creator_interests,omitempty"`

	// CreatorGender Filter creators based on their gender. **Values:** `male`, `female`.
	CreatorGender *GetCreatorMarketplaceCreatorsParamsCreatorGender `form:"creator_gender,omitempty" json:"creator_gender,omitempty"`

	// CreatorStates Filter creators based on their state location. Input will be the state ISO code list.  Note that we only support US states at this time. `creator_countries=[‘US’]` must be defined.
	CreatorStates *string `form:"creator_states,omitempty" json:"creator_states,omitempty"`

	// CreatorMinEngagedAccounts Minimum engagement metric of the audience for a creator's content. **Values:** `0`, `2000`, `10000`, `50000`, `100000`.
	CreatorMinEngagedAccounts *GetCreatorMarketplaceCreatorsParamsCreatorMinEngagedAccounts `form:"creator_min_engaged_accounts,omitempty" json:"creator_min_engaged_accounts,omitempty"`

	// CreatorMaxEngagedAccounts Maximum engagement metric of the audience for a creator's content. **Values:** `2000`, `10000`, `50000`, `100000`
	CreatorMaxEngagedAccounts *GetCreatorMarketplaceCreatorsParamsCreatorMaxEngagedAccounts `form:"creator_max_engaged_accounts,omitempty" json:"creator_max_engaged_accounts,omitempty"`

	// MajorAudienceAgeBucket Filter creators based on their audience's age group. **Values:** `18_to_24`, `25_to_34`, `35_to_44`, `45_to_54`, `55_to_64`, `65_and_above`
	MajorAudienceAgeBucket *GetCreatorMarketplaceCreatorsParamsMajorAudienceAgeBucket `form:"major_audience_age_bucket,omitempty" json:"major_audience_age_bucket,omitempty"`

	// MajorAudienceGender Filter creators based on their audience's gender. **Values:** `male`, `female`
	MajorAudienceGender *GetCreatorMarketplaceCreatorsParamsMajorAudienceGender `form:"major_audience_gender,omitempty" json:"major_audience_gender,omitempty"`

	// MajorAudienceCountries Filter creators based on the location of their audience. Input will be the country ISO code list.
	MajorAudienceCountries *string `form:"major_audience_countries,omitempty" json:"major_audience_countries,omitempty"`

	// MajorAudienceStates Filter creators based on the state location of their audience. Input will be the state ISO code list.  Note that we only support US states at this time. `major_audience_countries=[‘US’]` must be defined.
	MajorAudienceStates *string `form:"major_audience_states,omitempty" json:"major_audience_states,omitempty"`

	// Query A free-text search to find creators based on a list of keywords (e.g., username or content-related terms). For example: to find travel-related accounts, use `query=travel`.
	Query *string `form:"query,omitempty" json:"query,omitempty"`

	// SimilarToCreators A list of creators similar to the specified creator. **Limited to only onboarded creators,** input can be a list of usernames and the maximum username input is 5.
	SimilarToCreators *string `form:"similar_to_creators,omitempty" json:"similar_to_creators,omitempty"`

	// RecommendationType The recommendation type based on information including creative style, partnership experience, follower demographics and more for your brand. We support the following values:  - `most_relevant_for_me`: Return creators most relevant for you. - `high_ad_performance`: Return creators who are expected to deliver high ad performance for you. - `most_ads_experience`: Return creators with the most ads experience. - `similar_brands`: Return creators who've partnered with brands like you. - `similar_audience`: Return creators similar to creators you've worked with before.
	RecommendationType *string `form:"recommendation_type,omitempty" json:"recommendation_type,omitempty"`

	// Username The creator's Instagram username
	Username *string `form:"username,omitempty" json:"username,omitempty"`

	// CustomAudienceId ID of the custom audience (obtained from the `creator_marketplace_brand_info` endpoint) to filter creators whose follower base overlaps with the specified audience.
	CustomAudienceId *string `form:"custom_audience_id,omitempty" json:"custom_audience_id,omitempty"`

	// ReelsInteractionRate The percentage of views that liked, commented, shared and saved this creator’s recent reels. This is calculated as the number of views that engaged with the reels divided by the total number of initial views.
	ReelsInteractionRate interface{} `form:"reels_interaction_rate,omitempty" json:"reels_interaction_rate,omitempty"`

	// MajorAudienceDeviceType Filter creators based on their audience's primary device type. Results are filtered to only include creators whose majority audience uses the specified device type(s). Accepts an array of values. **Values:** `ios`, `android`
	MajorAudienceDeviceType *string `form:"major_audience_device_type,omitempty" json:"major_audience_device_type,omitempty"`

	// CreatorLatestPostActivity Filter creators who recently created a public post or reel. Results are filtered to only include creators who have posted within the specified time window.  Accepts a single value. **Values:** `last_7_days`, `last_30_days`, `last_90_days`
	CreatorLatestPostActivity *GetCreatorMarketplaceCreatorsParamsCreatorLatestPostActivity `form:"creator_latest_post_activity,omitempty" json:"creator_latest_post_activity,omitempty"`

	// CreatorFollowerGrowth Filter creators with top follower growth within the last 30 days, compared with similar creators. Results are filtered to only include creators whose follower growth ranks in the specified percentile.  Accepts a single value. **Values:** `top_10_percent`, `top_30_percent`, `top_50_percent`
	CreatorFollowerGrowth *GetCreatorMarketplaceCreatorsParamsCreatorFollowerGrowth `form:"creator_follower_growth,omitempty" json:"creator_follower_growth,omitempty"`
}

